/* echo-test.json — restyled from old .delay-slider/.status-recording/.echo-visualizer block */
/* native range inputs (delay-slider, monitor-delay) lose Bootstrap's custom .form-range styling
   once Bootstrap's CSS is gone; give the browser-default track an amber thumb instead of rebuilding
   the whole custom track/thumb chrome */
input[type="range"]{accent-color:var(--amber);}
.status-recording{color:var(--red);animation:echo-blink 1s infinite;}
@keyframes echo-blink{0%,100%{opacity:1}50%{opacity:.5}}
/* #status-alert: the tool script overwrites this element's className to a bare "alert alert-<type>"
   string on every status update, so the structural box styling normally supplied by .status-message
   must live on the id selector to survive those updates. */
#status-alert{padding:.6rem .85rem;margin-bottom:.85rem;border-radius:4px;font-size:13px;border:1px solid var(--border);}
/* utility classes emitted dynamically by the tool script (testResults.innerHTML) that have no
   equivalent in the new design system */
.text-success{color:var(--success);}
.fs-1{font-size:2rem;}
.small{font-size:12px;}
